rce_three_module_closure_revision\\\")\\n\\n\\nSTORE SELECTED COMPLETE METHODS services/aos-api/aos_api/ecommerce_workshop_three_module_closure_store.py fullFileSHA 79954f70a921f7c1e0115ed6b759358e8c8421891a433b2c4efe189a430c83d8\\n\\n_STATUS = {\\n    \\\"prepared\\\": CanonicalItemOutcome.IN_PROGRESS,\\n    \\\"reserved\\\": CanonicalItemOutcome.IN_PROGRESS,\\n    \\\"accepted\\\": CanonicalItemOutcome.IN_PROGRESS,\\n    \\\"frozen\\\": CanonicalItemOutcome.IN_PROGRESS,\\n    \\\"applied\\\": CanonicalItemOutcome.SUCCEEDED,\\n    \\\"adopted\\\": CanonicalItemOutcome.SUCCEEDED,\\n    \\\"failed\\\": CanonicalItemOutcome.FAILED,\\n    \\\"rejected\\\": CanonicalItemOutcome.FAILED,\\n    \\\"cancelled\\\": CanonicalItemOutcome.FAILED,\\n    \\\"unknown\\\": CanonicalItemOutcome.UNKNOWN,\\n    \\\"disputed\\\": CanonicalItemOutcome.DISPUTED,\\n    \\\"skipped_withdrawn\\\": CanonicalItemOutcome.SKIPPED,\\n}\\n\\n    def __init__(\\n        self,\\n        connect_factory: Callable[[TenantScope], Any] = connect,\\n        read_connect_factory: Callable[[TenantScope], Any] | None = None,\\n        serializable_connect_factory: Callable[[TenantScope], Any] | None = None,\\n    ) -> None:\\n        self._connect = connect_factory\\n        self._read_connect = read_connect_factory or (\\n            connect_factory if connect_factory is not connect else connect_read_only\\n        )\\n        self._serial_connect = serializable_connect_factory or (\\n            connect_factory if connect_factory is not connect else connect_serializable\\n        )\\n\\n    def _append(self, scope: TenantScope, table: str, identity: str, item: Any, created_at: Any) -> Any:\\n        self._assert_tenant(scope, item)\\n        content_hash = item.content_hash\\n        with self._serial_connect(scope) as conn:\\n            conn.execute(\\n                f\\\"INSERT INTO {table}(org_id,project_id,binding_id,revision,module,closure_id,content_hash,authority_data,created_at) VALUES (%s,%s,%s,1,%s,%s,%s,%s::jsonb,%s) ON CONFLICT DO NOTHING\\\",\\n                (*scope.key, identity, getattr(item, \\\"module\\\", None), getattr(item, \\\"closure_id\\\", None) or item.closure_ref.resource_id, content_hash, self._json(item.model_dump(mode=\\\"json\\\", by_alias=True)), created_at),\\n            )\\n            row = conn.execute(\\n                f\\\"SELECT authority_data,content_hash FROM {table} WHERE org_id=%s AND project_id=%s AND binding_id=%s AND revision=1\\\",\\n                (*scope.key, identity),\\n            ).fetchone()\\n            if row is None or row[\\\"content_hash\\\"] != content_hash:\\n                raise ThreeModuleClosureBlocked(\\\"THREE_MODULE_BINDING_IDEMPOTENCY_CONFLICT\\\")\\n            conn.commit()\\n        return type(item).model_validate(row[\\\"authority_data\\\"])\\n\\n    def append_closure(self, scope: TenantScope, item: ThreeModuleClosureRevision) -> ThreeModuleClosureRevision:\\n        self._assert_tenant(scope, item)\\n        with self._serial_connect(scope) as conn:\\n            conn.execute(\\n                \\\"INSERT INTO ecommerce_three_module_closure_revision(org_id,project_id,closure_id,revision,module,source_id,content_hash,authority_data,created_at) VALUES (%s,%s,%s,1,%s,%s,%s,%s::jsonb,%s) ON CONFLICT DO NOTHING\\\",\\n                (*scope.key, item.closure_id, item.module.value, item.source_ref.resource_id, item.content_hash, self._json(item.model_dump(mode=\\\"json\\\", by_alias=True)), item.compiled_at),\\n            )\\n            row = conn.execute(\\n                \\\"SELECT authority_data,content_hash FROM ecommerce_three_module_closure_revision WHERE org_id=%s AND project_id=%s AND closure_id=%s AND revision=1\\\",\\n                (*scope.key, item.closure_id),\\n            ).fetchone()\\n            if row is None or row[\\\"content_hash\\\"] != item.content_hash:\\n                raise ThreeModuleClosureBlocked(\\\"THREE_MODULE_CLOSURE_IDEMPOTENCY_CONFLICT\\\")\\n            conn.commit()\\n        return ThreeModuleClosureRevision.model_validate(row[\\\"authority_data\\\"])\\n\\n    def _source_row(self, scope: TenantScope, table: str, identity: str, source: ClosureExactRef) -> dict[str, Any]:\\n        with self._read_connect(scope) as conn:\\n            row = conn.execute(\\n                f\\\"SELECT authority_data,content_hash FROM {table} WHERE org_id=%s AND project_id=%s AND {identity}=%s AND revision=%s\\\",\\n                (*scope.key, source.resource_id, source.revision),\\n            ).fetchone()\\n        if row is None or f\\\"sha256:{row['content_hash']}\\\" != source.content_hash:\\n            raise ThreeModuleClosureBlocked(\\\"THREE_MODULE_SOURCE_MISSING_OR_DRIFTED\\\")\\n        return self._value(row[\\\"authority_data\\\"])\\n\\n    def resolve_domain_items(self, scope: TenantScope, module: ThreeModule, source: ClosureExactRef) -> list[ThreeModuleItemOutcome]:\\n        if module is ThreeModule.CREATOR:\\n            data = self._source_row(scope, \\\"ecommerce_creator_batch_start_decision_revision\\\", \\\"decision_id\\\", source)\\n            observations = self._observations(scope, \\\"ecommerce_creator_lane_observation\\\", \\\"decision_id\\\", source.resource_id, \\\"laneId\\\")\\n            raw = []\\n            for lane in data.get(\\\"lanes\\\", []):\\n                key = str(lane[\\\"laneId\\\"])\\n                observation = observations.get(key)\\n                status = str((observation or lane).get(\\\"resolvedOutcome\\\") or (observation or lane).get(\\\"outcome\\\"))\\n                receipt = (observation or lane).get(\\\"actionReceiptRef\\\")\\n                raw.append((key, status, receipt))\\n        elif module is ThreeModule.PRICE:\\n            data = self._source_row(scope, \\\"ecommerce_price_disposition_revision\\\", \\\"disposition_id\\\", source)\\n            with self._read_connect(scope) as conn:\\n                row = conn.execute(\\n                    \\\"SELECT authority_data FROM ecommerce_price_disposition_observation WHERE org_id=%s AND project_id=%s AND authority_data->'dispositionRef'->>'resourceId'=%s ORDER BY created_at DESC LIMIT 1\\\",\\n                    (*scope.key, source.resource_id),\\n                ).fetchone()\\n            observation = None if row is None else self._value(row[\\\"authority_data\\\"])\\n            status = str((observation or {}).get(\\\"resolvedOutcome\\\") or (observation or {}).get(\\\"outcome\\\") or data.get(\\\"lifecycle\\\", \\\"prepared\\\"))\\n            receipt = (observation or {}).get(\\\"receiptRef\\\")\\n            raw = [(str(ref[\\\"resourceId\\\"]), status, receipt) for ref in data.get(\\\"targetRefs\\\", [])]\\n        else:\\n            data = self._source_row(scope, \\\"ecommerce_customer_batch_start_decision_revision\\\", \\\"decision_id\\\", source)\\n            observations = self._observations(scope, \\\"ecommerce_customer_dispatch_observation\\\", \\\"decision_id\\\", source.resource_id, \\\"itemKey\\\")\\n            raw = []\\n            for binding in data.get(\\\"items\\\", []):\\n                key = str(binding[\\\"itemKey\\\"])\\n                observation = observations.get(key)\\n                status = str((observation or binding).get(\\\"resolvedState\\\") or (observation or binding).get(\\\"state\\\"))\\n                receipt = (observation or binding).get(\\\"actionReceiptRef\\\")\\n                raw.append((key, status, receipt))\\n        items: list[ThreeModuleItemOutcome] = []\\n        for key, status, receipt in sorted(raw):\\n            outcome = _STATUS.get(status)\\n            if outcome is None:\\n                raise ThreeModuleClosureBlocked(\\\"THREE_MODULE_ORIGINAL_STATUS_UNMAPPED\\\")\\n            items.append(ThreeModuleItemOutcome(\\n                itemKey=key, originalStatus=status, canonicalOutcome=outcome,\\n                originalRef=self._original_ref(source, key), receiptRef=self._ref(receipt),\\n            ))\\n        return items\\n\\n    def latest_bindings(self, scope: TenantScope, module: ThreeModule) -> dict[str, Any]:\\n        with self._connect(scope) as conn:\\n            closure_row = conn.execute(\\n                \\\"SELECT authority_data FROM ecommerce_three_module_closure_revision WHERE org_id=%s AND project_id=%s AND module=%s ORDER BY created_at DESC LIMIT 1\\\",\\n                (*scope.key, module.value),\\n            ).fetchone()\\n            if closure_row is None:\\n                return {\\\"closure\\\": None, \\\"usage\\\": None, \\\"effect\\\": None, \\\"handoff\\\": None}\\n            closure = ThreeModuleClosureRevision.model_validate(closure_row[\\\"authority_data\\\"])\\n            result: dict[str, Any] = {\\\"closure\\\": closure}\\n            for key, table, model in (\\n                (\\\"usage\\\", \\\"ecommerce_three_module_usage_binding_revision\\\", ThreeModuleUsageBindingRevision),\\n                (\\\"effect\\\", \\\"ecommerce_three_module_effect_binding_revision\\\", ThreeModuleEffectBindingRevision),\\n                (\\\"handoff\\\", \\\"ecommerce_three_module_handoff_binding_revision\\\", ThreeModuleHandoffBindingRevision),\\n            ):\\n                row = conn.execute(\\n                    f\\\"SELECT authority_data FROM {table} WHERE org_id=%s AND project_id=%s AND closure_id=%s ORDER BY created_at DESC LIMIT 1\\\",\\n                    (*scope.key, closure.closure_id),\\n                ).fetchone()\\n                result[key] = None if row is None else model.model_validate(row[\\\"authority_data\\\"])\\n        return result\\n\\nCURRENT ROUTE services/aos-api/aos_api/routers/ecommerce_workshop.py fullFileSHA 78db249f25f3e51b85362e2ca3c50e56575ed960b6371d22f0dc17f6bc454220\\n@router.get(\\n    \\\"/views/{module}/closure-contributions\\\",\\n    response_model=ThreeModuleClosureContributionView,\\n    operation_id=\\\"ecommerceWorkshopThreeModuleClosureContributionViewGet\\\",\\n    responses=_ERRORS,\\n)\\ndef get_three_module_closure_contribution_view(\\n    request: Request,\\n    module: ThreeModule,\\n    principal: PrincipalDependency,\\n    catalog: CatalogDependency,\\n    read_catalog: ReadCatalogDependency,\\n    service: ThreeModuleClosureDependency,\\n    readonly: CreatorClosureReadonlyDependency,\\n) -> ThreeModuleClosureContributionView:\\n    _reject_query_parameters(request)\\n    if module is ThreeModule.CREATOR:\\n        admission = _require_creator_growth_installation(principal=principal, catalog=read_catalog)\\n        if not isinstance(admission, EcommerceWorkshopModuleReadinessResponse):\\n            raise ApiError(code=\\\"CREATOR_CLOSURE_READ_ADMISSION_UNAVAILABLE\\\",\\n                           message=\\\"当前闭环贡献读取准入不可核验。\\\", status_code=503)\\n        if any(b.reason_code == \\\"INSTALLED_ASSET_READONLY\\\" for b in admission.item.blockers):\\n            try:\\n                return readonly.read(TenantScope(principal.org_id, principal.project_id))\\n            except CreatorClosureReadonlyError as exc:\\n                raise ApiError(code=exc.code, message=\\\"当前闭环贡献暂不可读，请核对保存记录或读取范围。\\\",\\n                               status_code=503) from exc\\n        return service.contribution_view(TenantScope(principal.org_id, principal.project_id), module)\\n    _require_three_module_installation(module, principal=principal, catalog=catalog)\\n    return service.contribution_view(TenantScope(principal.org_id, principal.project_id), module)\\n\\nEVIDENCE implementation-plan-r1.md\\n# 价格闭环保存贡献读取：文件级方案\\n\\n## 方案复习与边界\\n\\n已读产品v2/08价格治理、技术57-W6-09含2026-08-25实施封板、原closure models/service/store/DDL、原creator readonly及测试、原price页面和parser。基线m1 804a0279，Authority2035，唯一owner原线程不变。完整231Goal、原唯一真人授权、daily/every aos最新m1同原卷完整PG→API→Web和aos2不重启保留。\\n\\n本波只读取已保存price closure及usage/effect/handoff binding，不临时compile/bind/resolve source、不授运行或当前预算/审批、Handoff consume、Memory promotion。五轴独立；unknown usage保持null，immature不造完成，consumed不冒充accepted。原库READONLY/HostworkerProviderOFF/unknown旧12不重放/disabledSchedule不启用/source不读/noPush不变。\\n\\n## 文件与归属\\n\\n主Task已拥有`services/aos-api/aos_api/routers/ecommerce_workshop.py`、`services/aos-api/tests/test_ecommerce_workshop_read_http.py`、本E和原D-wave。额外同owner非重叠Task先登记两个文件及自身E：\\n\\n- `services/aos-api/aos_api/ecommerce_three_module_closure_readonly.py`：在原CreatorClosureReadonlyReader中以固定类属性选择模块，共享现有hash/ledger/绑定校验；新增PriceClosureReadonlyReader子类固定PRICE，稳定price错误码包装。原Creator公开类、构造和默认read保持creator；没有来自query的模块选择。共享私有_row/_decode加默认creator的module参数，仍只允许creator/price。\\n- `services/aos-api/tests/test_ecommerce_three_module_closure_readonly.py`：原creator回归保留；新增原producer价格非空/空、模块隔离、五轴、strict raw、SQL门、敏感和失败场景。\\n\\n不修改原domain producer/Store/DDL、AIP、Web/parser/CSS或用户dirty。route在原creator分支之外新增price分支，使用ReadCatalog的价格readiness typed installed readonly标记，才选择Price reader；原legacy成功、creator与customer及全部POST保持原门。任何额外文件先登记，不直接复制writer/客户端状态机。\\n\\n## 共享算法与价格字段约束\\n\\n现有64KiB单行SQLCASE、1MiB整体/DTO、只取最新closure和该closure下三binding的原视图语义保持（此视图没有全历史计数，不引入截断计数）。固定四表tenant双列参数、LIMIT1，created_at DESC与identity确定性tie-break；不以cutoff WHERE隐藏未来选中坏行。同一个已核实READ ONLY REPEATABLE READ连接，transaction_timestamp为cutoff。\\n\\n价格专用入口在同事务固定SET LOCAL statement_timeout=3000ms/lock_timeout=500ms，查询间和返回前monotonic10秒门。价格SQL对外层identity/closure/source id作240字符CASE门，不传输巨大坏id；payload仍64KiB CASE，超限整体失败。creator原SQL/连接行为保持。没有分页或无界fetchall。\\n\\n模块贯穿SQL参数、Compile request source类型、派生closure_id、row.module、DTO module；price sourceRef只能PriceDispositionRevision。binding外层module原producer可NULL，允许NULL或price；不能借creator closure/ref。closure hash仍原typed sourceRef/items经canonical_hash(default=str)，不改为model_dump另一算法；三binding按原payload字段与原typed refs签名/派生ID，exact closure ref、原_STATUS映射、_ledger守恒、时间与privacy沿用。\\n\\n价格增加raw完整字段和递归strict int/bool/有限number检查，并要求完整typed model_dump JSON与raw相等，防默认值/coercion吞字段；usage settlement必须等于quality，符合原resolver和前端合同。保留未来immature cutoff合法状态，mature只沿原canonical成熟规则，不新建第二套成熟裁决。原public ResourceRef/HandoffResourceRef合同约束Task/TaskRun，拒绝任意扩展。前端parser全串拒绝mobile/openid/email/address/contactvalue/providerpayload，价格在后端也稳定拒绝无法公开的同类内容；不脱敏后冒充hash仍有效。creator既有正常行为与错误前缀保持。\\n\\nPrice子类只将原内部creator错误映射为PRICE_CLOSURE_READ_*，不吞异常补四null；正常空snapshot才四null+四真实缺口。输出沿原Service.contribution_view，再完整model_validate DTO，明确commands[]/handoffConsumeAllowed=false/memoryPromotionAllowed=false/externalEffectsAllowed=false。保存facts不提升当前source/Receipt/gate权限。\\n\\n## 门禁与验收\\n\\n先在本E执行原producer price非空四记录typed hash与五轴隔离probe；登记额外文件；冻结完整方案/原source/原DDL/原probe，独立Prime route PASS合法消费后才产品RED。RED覆盖price未准入/creator误读风险、正常/readonly分流、tenant/query/unknown admission、SDK形状和稳定非200；专项覆盖source type/outer module/ref/时间/hash/ledger/raw缺失/数字bool/unknown null/immature/request_more/隐私/SQLCASE及错误prefix。\\n\\n最小实现后专项与creator相邻、原三module/价格处置/root/catalog冻结累计；原w6_009隔离tmpfs PG、原producer合成price与creator/foreign行、same snapshot、RLS/FORCE/25006/SQL超大NULL/隐私；独立代码和route质量。之后精确提交、fresh最新后端冻源/maintenance controller门/新意图API-only，原真人正常GET+正式price SDK、query400/匿名401、原650完整指纹不变、原稿三视口和现场Prime。准确两个slice Delivery/maintenance完整剩余接续/Authority七强，再下一登记helper。\\n\\n不把隔离fixture、读取200/页面可见、测试或review PASS当经营首链。视觉比较保留真实空/unknown和禁入提示，不复制原稿47SKU或价格/异常。API-only读波不替代daily/every aos全面重启。回滚只撤price路由准入与本共享reader增量，需fresh维护门；不reset、不迁移原库、不覆盖dirty。\\n\\n\\nEVIDENCE producer-probe-result-r1.json\\n{\\n  \\\"syntheticMemoryOnly\\\": true,\\n  \\\"databaseOrHttpCalls\\\": 0,\\n  \\\"productionAuthority\\\": false,\\n  \\\"module\\\": \\\"price\\\",\\n  \\\"originalProducerTypedHashVerified\\\": true,\\n  \\\"jsonDumpHashIsDifferent\\\": true,\\n  \\\"itemLedger\\\": {\\n    \\\"total\\\": 2,\\n    \\\"succeeded\\\": 1,\\n    \\\"unknown\\\": 1,\\n    \\\"state\\\": \\\"partial\\\"\\n  },\\n  \\\"usageQuantity\\\": null,\\n  \\\"effectAccepted\\\": true,\\n  \\\"effectCompleted\\\": false,\\n  \\\"maturity\\\": \\\"immature\\\",\\n  \\\"handoffTransport\\\": \\\"consumed\\\",\\n  \\\"businessDecision\\\": \\\"request_more\\\",\\n  \\\"bindingIds\\\": {\\n    \\\"usage\\\": \\\"three-module-usage-ac209243302715cb18841b8a\\\",\\n    \\\"effect\\\": \\\"three-module-effect-c426ad81d0c4e2da284ce526\\\",\\n    \\\"handoff\\\": \\\"three-module-handoff-0764423beaee6335b7ecd014\\\"\\n  },\\n  \\\"originalServiceSha\\\": \\\"abb7798aae5fe3ca87ec0a05e2445bdbbf16cb54663009709bff20252458ea40\\\",\\n  \\\"wholeGoalComplete\\\": false\\n}\\n\\nEVIDENCE reader-scope-readback-r1.json\\n{\\n  \\\"schema\\\": \\\"aos-memory-task-receipt/v1\\\",\\n  \\\"task_id\\\": \\\"qyh-price-closure-bounded-reader-20261015\\\",\\n  \\\"owner\\\": \\\"codex-01a13484-f019-7d82-94ce-812396db9124\\\",\\n  \\\"base_revision\\\": \\\"AOS-002035\\\",\\n  \\\"scope\\\": [\\n    \\\"aos-platform/services/aos-api/aos_api/ecommerce_three_module_closure_readonly.py\\\",\\n    \\\"aos-platform/services/aos-api/tests/test_ecommerce_three_module_closure_readonly.py\\\",\\n    \\\"aos-platform/.evidence/qyh-price-closure-bounded-reader-20261015\\\"\\n  ],\\n  \\\"excluded_scope\\\": [\\n    \\\"aos-platform/apps/web\\\",\\n    \\\"aos-platform/maintenance/qiyuehui-restored-data-volume\\\"\\n  ],\\n  \\\"expected_outputs\\\": [\\n    \\\"Full231Goal and original authorization retained; only price closure saved view, no compiler/bind/consume/source/provider effects.\\\",\\n    \\\"Share original creator closure codec with fixed price entry and error prefix; preserve creator normal/default and customer legacy. Independent plan before RED/code, strict price raw/tenant/hash/ledger/exact bindings/privacy/time/SQL bounds.\\\",\\n    \\\"Original producer price nonempty five axes, creator regression, frozen cumulative/native originalDDL/realSDK and650/live independent gates; accurate slice Delivery only, whole Goal remains ACTIVE.\\\"\\n  ],\\n  \\\"lease_expires_at\\\": \\\"2026-10-15T08:00:00+00:00\\\",\\n  \\\"status\\\": \\\"ACTIVE\\\",\\n  \\\"created_at\\\": \\\"2026-10-15T11:21:31+08:00\\\"\\n}\"}}"}],"timestamp":1792034601289}}
{"type":"message_end","message":{"role":"user","content":[{"type":"text","text":"{\"schema\": \"aos-material-review/v1\", \"request_id\": \"qyh-price-closure-read-admission-20261015-design-r1\", \"task_id\": \"qyh-price-closure-read-admission-20261015\", \"owner\": \"codex-01a13484-f019-7d82-94ce-812396db9124\", \"kind\": \"route\", \"baseline\": {\"head\": \"804a0279aa3d426a693504cb3336fb5a8ca4d149\", \"authority_revision\": \"AOS-002035\", \"files\": {\".evidence/qyh-price-closure-read-admission-20261015/design-review-material-r1.txt\": \"eef5d4b4423e7393a6c3448cbca83cd694ebaaa7514dcc7374dc885191f78b08\"}}, \"claims\": [\"方案复用原closure与三binding的typed签名/派生ID/ledger及原五轴合同，新增固定price入口不复制权威引擎；creator正常行为和customer/POST原门保留。\", \"价格专用只读snapshot、SQL尺寸门、strict raw及tenant/module/exact/time/privacy、稳定失败与空命令设计可实施，不把已保存bridge当当前源或预算审批。\", \"额外两个文件已非重叠登记；RED/原producer/creator邻接/原DDL隔离PG/冻结/独立质量/真实SDK650及原稿现场验收明确，未声称代码或经营Goal完成。\"], \"materials\": {\".evidence/qyh-price-closure-read-admission-20261015/design-review-material-r1.txt\": \"PRE-IMPLEMENTATION DESIGN REVIEW. No product candidate/route admission/deployment yet. Original complete231Goal retained. Review shared codec fixed PRICE entry plus preserved CREATOR behavior, not operating/source/gate authority. Source resolver excerpts explain producer only, GET never invokes them.\\n\\n\\nFULL FILE services/aos-api/aos_api/ecommerce_workshop_three_module_closure.py SHA abb7798aae5fe3ca87ec0a05e2445bdbbf16cb54663009709bff20252458ea40\\n\\\"\\\"\\\"W6-09 canonical closure bridge for creator, price and customer modules.\\n\\nThe bridge never accepts caller-declared aggregate success.  Item outcomes,\\nusage, effect maturity and handoff decisions are resolved from their existing\\ntenant authorities and remain five independent axes.\\n\\\"\\\"\\\"\\nfrom __future__ import annotations\\n\\nimport hashlib\\nimport json\\nfrom datetime import UTC, datetime\\nfrom enum import StrEnum\\nfrom typing import Any\\n\\nfrom pydantic import Field, model_validator\\n\\nfrom aos_api.aip_contracts import AipContractModel, TenantContext\\nfrom aos_api.tenant_scope import TenantScope\\n\\n\\nTHREE_MODULE_CLOSURE_SCHEMA_VERSION = \\\"aos.ecommerce-workshop.three-module-closure/v1\\\"\\n\\n\\ndef canonical_hash(value: Any) -> str:\\n    payload = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(\\\",\\\", \\\":\\\"), default=str)\\n    return hashlib.sha256(payload.encode()).hexdigest()\\n\\n\\nclass ThreeModuleClosureBlocked(RuntimeError):\\n    code = \\\"THREE_MODULE_CLOSURE_BLOCKED\\\"\\n\\n\\nclass ThreeModuleClosureConflict(ThreeModuleClosureBlocked):\\n    code = \\\"THREE_MODULE_CLOSURE_CONFLICT\\\"\\n\\n\\nclass ThreeModule(StrEnum):\\n    CREATOR = \\\"creator\\\"\\n    PRICE = \\\"price\\\"\\n    CUSTOMER = \\\"customer\\\"\\n\\n\\nclass CanonicalItemOutcome(StrEnum):\\n    IN_PROGRESS = \\\"in_progress\\\"\\n    SUCCEEDED = \\\"succeeded\\\"\\n    FAILED = \\\"failed\\\"\\n    UNKNOWN = \\\"unknown\\\"\\n    DISPUTED = \\\"disputed\\\"\\n    SKIPPED = \\\"skipped\\\"\\n\\n\\nclass ClosureState(StrEnum):\\n    EMPTY = \\\"empty\\\"\\n    IN_PROGRESS = \\\"in_progress\\\"\\n    COMPLETED = \\\"completed\\\"\\n    FAILED = \\\"failed\\\"\\n    PARTIAL = \\\"partial\\\"\\n    UNKNOWN = \\\"unknown\\\"\\n\\n\\nclass ClosureExactRef(AipContractModel):\\n    resource_type: str = Field(min_length=1, max_length=120)\\n    resource_id: str = Field(min_length=1, max_length=240)\\n    revision: int = Field(ge=1)\\n    content_hash: str = Field(pattern=r\\\"^sha256:[0-9a-f]{64}$\\\")\\n    receipt_id: str = Field(min_length=1, max_length=240)\\n\\n\\nclass CompileThreeModuleClosureRequest(AipContractModel):\\n    module: ThreeModule\\n    source_ref: ClosureExactRef\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _source_type(self) -> \\\"CompileThreeModuleClosureRequest\\\":\\n        expected = {\\n            ThreeModule.CREATOR: \\\"CreatorBatchStartDecisionRevision\\\",\\n            ThreeModule.PRICE: \\\"PriceDispositionRevision\\\",\\n            ThreeModule.CUSTOMER: \\\"CustomerBatchStartDecisionRevision\\\",\\n        }\\n        if self.source_ref.resource_type != expected[self.module]:\\n            raise ValueError(\\\"three-module sourceRef type drifted\\\")\\n        return self\\n\\n\\nclass ThreeModuleItemOutcome(AipContractModel):\\n    item_key: str = Field(min_length=1, max_length=240)\\n    original_status: str = Field(min_length=1, max_length=80)\\n    canonical_outcome: CanonicalItemOutcome\\n    original_ref: ClosureExactRef\\n    receipt_ref: ClosureExactRef | None = None\\n\\n\\nclass ThreeModuleClosureLedger(AipContractModel):\\n    total: int = Field(ge=0)\\n    in_progress: int = Field(ge=0)\\n    succeeded: int = Field(ge=0)\\n    failed: int = Field(ge=0)\\n    unknown: int = Field(ge=0)\\n    disputed: int = Field(ge=0)\\n    skipped: int = Field(ge=0)\\n    state: ClosureState\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _conserved(self) -> \\\"ThreeModuleClosureLedger\\\":\\n        values = [self.in_progress, self.succeeded, self.failed, self.unknown, self.disputed, self.skipped]\\n        if self.total != sum(values):\\n            raise ValueError(\\\"three-module closure ledger must conserve items\\\")\\n        nonzero = sum(value > 0 for value in values)\\n        expected = (\\n            ClosureState.EMPTY if self.total == 0 else\\n            ClosureState.COMPLETED if self.succeeded == self.total else\\n            ClosureState.FAILED if self.failed == self.total else\\n            ClosureState.UNKNOWN if self.unknown == self.total else\\n            ClosureState.IN_PROGRESS if self.in_progress == self.total else\\n            ClosureState.PARTIAL if nonzero > 1 else\\n            ClosureState.PARTIAL\\n        )\\n        if self.state is not expected:\\n            raise ValueError(\\\"three-module closure state does not match item algebra\\\")\\n        return self\\n\\n\\nclass ThreeModuleClosureRevision(AipContractModel):\\n    tenant: TenantContext\\n    closure_id: str\\n    revision: int = 1\\n    module: ThreeModule\\n    source_ref: ClosureExactRef\\n    items: list[ThreeModuleItemOutcome] = Field(default_factory=list, max_length=2000)\\n    ledger: ThreeModuleClosureLedger\\n    content_hash: str = Field(pattern=r\\\"^[0-9a-f]{64}$\\\")\\n    compiled_by: str\\n    compiled_at: datetime\\n\\n\\nclass BindThreeModuleUsageRequest(AipContractModel):\\n    closure_ref: ClosureExactRef\\n    usage_receipt_id: str = Field(min_length=1, max_length=240)\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _closure(self) -> \\\"BindThreeModuleUsageRequest\\\":\\n        if self.closure_ref.resource_type != \\\"ThreeModuleClosureRevision\\\":\\n            raise ValueError(\\\"closureRef drifted\\\")\\n        return self\\n\\n\\nclass ThreeModuleUsageBindingRevision(AipContractModel):\\n    tenant: TenantContext\\n    binding_id: str\\n    revision: int = 1\\n    closure_ref: ClosureExactRef\\n    usage_receipt_ref: ClosureExactRef\\n    lineage_id: str\\n    quality: str = Field(pattern=r\\\"^(measured|estimated|unknown)$\\\")\\n    quantity: float | None = Field(default=None, ge=0)\\n    unit: str\\n    adjustment_total: float = 0\\n    settlement: str = Field(pattern=r\\\"^(measured|estimated|unknown)$\\\")\\n    content_hash: str = Field(pattern=r\\\"^[0-9a-f]{64}$\\\")\\n    bound_at: datetime\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _unknown_has_no_quantity(self) -> \\\"ThreeModuleUsageBindingRevision\\\":\\n        if self.quality == \\\"unknown\\\" and self.quantity is not None:\\n            raise ValueError(\\\"unknown usage cannot invent zero or quantity\\\")\\n        if self.quality != \\\"unknown\\\" and self.quantity is None:\\n            raise ValueError(\\\"known usage requires canonical quantity\\\")\\n        return self\\n\\n\\nclass BindThreeModuleEffectRequest(AipContractModel):\\n    closure_ref: ClosureExactRef\\n    effect_review_id: str = Field(min_length=1, max_length=240)\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _closure(self) -> \\\"BindThreeModuleEffectRequest\\\":\\n        if self.closure_ref.resource_type != \\\"ThreeModuleClosureRevision\\\":\\n            raise ValueError(\\\"closureRef drifted\\\")\\n        return self\\n\\n\\nclass ThreeModuleEffectBindingRevision(AipContractModel):\\n    tenant: TenantContext\\n    binding_id: str\\n    revision: int = 1\\n    closure_ref: ClosureExactRef\\n    effect_review_ref: ClosureExactRef\\n    maturity_status: str = Field(pattern=r\\\"^(immature|mature|insufficient|unknown)$\\\")\\n    accepted: bool\\n    effect_completed: bool\\n    sample_count: int = Field(ge=0)\\n    min_sample: int = Field(ge=1)\\n    cutoff_at: datetime\\n    observed_at: datetime\\n    content_hash: str = Field(pattern=r\\\"^[0-9a-f]{64}$\\\")\\n    bound_at: datetime\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _maturity_is_honest(self) -> \\\"ThreeModuleEffectBindingRevision\\\":\\n        if self.effect_completed != (self.maturity_status == \\\"mature\\\"):\\n            raise ValueError(\\\"effectCompleted must follow canonical maturity only\\\")\\n        return self\\n\\n\\nclass BindThreeModuleHandoffRequest(AipContractModel):\\n    closure_ref: ClosureExactRef\\n    handoff_id: str = Field(min_length=1, max_length=240)\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _closure(self) -> \\\"BindThreeModuleHandoffRequest\\\":\\n        if self.closure_ref.resource_type != \\\"ThreeModuleClosureRevision\\\":\\n            raise ValueError(\\\"closureRef drifted\\\")\\n        return self\\n\\n\\nclass ThreeModuleHandoffBindingRevision(AipContractModel):\\n    tenant: TenantContext\\n    binding_id: str\\n    revision: int = 1\\n    closure_ref: ClosureExactRef\\n    handoff_ref: ClosureExactRef\\n    transport_status: str\\n    business_decision: str | None = Field(default=None, pattern=r\\\"^(accepted|